"""Collision primitives generated by a sphere-mesh connection list.

Three things live here, and they exist because the cloth solver needs all three.

**The primitives.** A connection list over N spheres generates *bumpers*: one per sphere,
one tapered cone per connected sphere pair, one prysmoid (triangular slab) per
3-connection and one quad per 4-connection. These are the objects the solver resolves
cloth nodes against, and the objects its watchdog caches an index into.

**Their exact signed distance.** A sphere-mesh is by definition the boundary of a union of
interpolated balls, so the signed distance to a bumper spanning the spheres of a simplex is

    d(p) = min over the simplex of  |p - c(lambda)| - r(lambda)

with ``c`` and ``r`` interpolated linearly in the barycentric weight ``lambda``. That is
exact both outside and inside: for a union of balls the deepest containing ball is the one
whose surface is nearest, so the same expression that gives the distance outside gives the
clearance inside. Every distance function here evaluates that minimum exactly -- the corner
terms, the edge terms in closed form as round cones, and the interior term through the
plane tangent to all three spheres.

This deliberately differs from ``src.sphere_fit.spheremesh_distance`` in two ways, and the
difference is the point of having this module:

* that function approximates the cone term by clamping the projection onto the segment of
  centres and interpolating the radius at the clamped parameter, which is exact only when
  the two radii are equal;
* it decomposes a 3-connection into its three edges and never evaluates the slab, so a
  point resting on the middle of a triangle is reported as far outside the sphere-mesh when
  it is in fact sitting on it.

``spheremesh_distance`` stays exactly as it is -- it is the external fidelity metric that
has to remain comparable across versions, and ``plan.md`` is explicit that it must not
change. This module is what the topology validator measures with.

**Their adjacency.** The watchdog follows a cloth node from bumper to bumper along explicit
topological links, never by proximity in space. ``BumperGraph`` builds those links from the
connection list alone, so the validator can ask the only question that matters: as a node
slides across the body surface, does every step land on a bumper adjacent to the one it
came from, or does the walk break and force a brute-force rescan?
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Sequence

import numpy as np

__all__ = [
    "Bumper",
    "BumperGraph",
    "SPHERE",
    "CONE",
    "PRYSMOID",
    "QUAD",
    "sphere_distances",
    "round_cone_distances",
    "prysmoid_distances",
    "tangent_plane",
]

SPHERE = "sphere"
CONE = "cone"
PRYSMOID = "prysmoid"
QUAD = "quad"

# A cone whose centre separation barely exceeds the difference of its radii is one sphere
# swallowed by another with a numerically hopeless sliver attached; it carries no surface.
_MIN_CONE_SLACK = 1e-9

# The squared length of the in-plane part of a tangent-plane normal. At 1 the three spheres
# admit no common tangent plane -- their radii vary too fast for the centre spacing -- and
# the prysmoid degenerates to its three edge cones.
_MAX_TANGENT_IN_PLANE = 1.0 - 1e-12


@dataclass(frozen=True)
class Bumper:
    """One collision primitive, named by the spheres it spans.

    ``spheres`` keeps the order the connection gave, which matters for a quad: its rim is
    0-1, 1-2, 2-3, 3-0, and the diagonal 0-2 is an interior split, not a rim edge.
    """

    kind: str
    spheres: tuple[int, ...]

    def edges(self) -> tuple[tuple[int, int], ...]:
        """Sphere pairs forming this bumper's rim, each ordered lower index first."""
        if self.kind == SPHERE:
            return ()
        if self.kind == CONE:
            return (_ordered(self.spheres[0], self.spheres[1]),)
        if self.kind == PRYSMOID:
            first, second, third = self.spheres
            return (
                _ordered(first, second),
                _ordered(second, third),
                _ordered(third, first),
            )
        if self.kind == QUAD:
            corners = self.spheres
            return tuple(
                _ordered(corners[position], corners[(position + 1) % 4])
                for position in range(4)
            )
        raise ValueError(f"unknown bumper kind {self.kind!r}")

    def triangles(self) -> tuple[tuple[int, int, int], ...]:
        """Triangles this bumper's slab decomposes into, for distance evaluation."""
        if self.kind == PRYSMOID:
            return (self.spheres,)
        if self.kind == QUAD:
            first, second, third, fourth = self.spheres
            return ((first, second, third), (first, third, fourth))
        return ()

    def __str__(self) -> str:
        return f"{self.kind}{list(self.spheres)}"


def _ordered(first: int, second: int) -> tuple[int, int]:
    return (first, second) if first < second else (second, first)


# --------------------------------------------------------------------------- distances


def sphere_distances(
    points: np.ndarray, centers: np.ndarray, radii: np.ndarray
) -> np.ndarray:
    """(M, N) signed distance from every point to every sphere."""
    difference = points[:, None, :] - centers[None, :, :]
    return np.sqrt(np.einsum("mnk,mnk->mn", difference, difference)) - radii[None, :]


def round_cone_distances(
    points: np.ndarray,
    start_center: np.ndarray,
    start_radius: np.ndarray,
    end_center: np.ndarray,
    end_radius: np.ndarray,
) -> np.ndarray:
    """(M, K) exact signed distance to K tapered cones, spherical caps included.

    The closed form is the analytic solution of
    ``min over t in [0, 1] of |p - lerp(c0, c1, t)| - lerp(r0, r1, t)`` and therefore the
    exact boundary distance of the union of the interpolated balls. Points beyond either
    end fall onto that end's sphere, which is why the caps need no separate term.

    Cones whose centres are closer together than their radii differ describe one sphere
    swallowed by another; they are answered with the enclosing sphere's distance.
    """
    points = np.ascontiguousarray(points, dtype=np.float64)
    axis = end_center - start_center                                     # (K, 3)
    axis_squared = np.einsum("kj,kj->k", axis, axis)                     # (K,)
    radius_difference = start_radius - end_radius                        # (K,)
    lateral_squared = axis_squared - radius_difference ** 2              # (K,)

    degenerate = (axis_squared <= _MIN_CONE_SLACK) | (lateral_squared <= _MIN_CONE_SLACK)
    safe_axis_squared = np.where(degenerate, 1.0, axis_squared)
    inverse_axis_squared = 1.0 / safe_axis_squared

    offset = points[:, None, :] - start_center[None, :, :]               # (M, K, 3)
    along = np.einsum("mkj,kj->mk", offset, axis)                        # (M, K)
    beyond_end = along - safe_axis_squared

    perpendicular = (
        offset * safe_axis_squared[None, :, None] - axis[None, :, :] * along[..., None]
    )
    perpendicular_squared = np.einsum("mkj,mkj->mk", perpendicular, perpendicular)
    along_squared = along * along * safe_axis_squared
    beyond_squared = beyond_end * beyond_end * safe_axis_squared

    threshold = np.sign(radius_difference) * radius_difference ** 2 * perpendicular_squared
    on_end_cap = np.sign(beyond_end) * lateral_squared * beyond_squared > threshold
    on_start_cap = np.sign(along) * lateral_squared * along_squared < threshold

    distance = (
        np.sqrt(
            np.maximum(perpendicular_squared * lateral_squared * inverse_axis_squared, 0.0)
        )
        + along * radius_difference
    ) * inverse_axis_squared - start_radius[None, :]
    distance = np.where(
        on_end_cap,
        np.sqrt(perpendicular_squared + beyond_squared) * inverse_axis_squared
        - end_radius[None, :],
        distance,
    )
    distance = np.where(
        on_start_cap & ~on_end_cap,
        np.sqrt(perpendicular_squared + along_squared) * inverse_axis_squared
        - start_radius[None, :],
        distance,
    )

    if degenerate.any():
        enclosing_center = np.where(
            (start_radius >= end_radius)[:, None], start_center, end_center
        )
        enclosing_radius = np.maximum(start_radius, end_radius)
        fallback = sphere_distances(points, enclosing_center, enclosing_radius)
        distance = np.where(degenerate[None, :], fallback, distance)
    return distance


def tangent_plane(
    centers: np.ndarray, radii: np.ndarray
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    """The plane tangent to three spheres from one side, for T triangles at once.

    ``centers`` is (T, 3, 3) and ``radii`` is (T, 3). Returns
    ``(in_plane_normal, out_of_plane_scale, plane_axis, exists)``: the tangent normal for a
    point on the ``+plane_axis`` side of the centre triangle is
    ``in_plane_normal + out_of_plane_scale * plane_axis``, and the opposite face is the
    same expression with the sign of ``out_of_plane_scale`` flipped.

    A unit normal ``n`` is tangent to all three spheres when ``n . c_i + r_i`` is the same
    plane offset for every i. Those two difference equations fix ``n``'s component in the
    plane of the centres and leave only its out-of-plane magnitude free, and that magnitude
    is real only while the in-plane part is shorter than a unit vector. When it is not, the
    radii vary too fast for the centre spacing and the triangle has no flat face at all.
    """
    first_edge = centers[:, 1] - centers[:, 0]
    second_edge = centers[:, 2] - centers[:, 0]

    first_dot_first = np.einsum("tj,tj->t", first_edge, first_edge)
    second_dot_second = np.einsum("tj,tj->t", second_edge, second_edge)
    first_dot_second = np.einsum("tj,tj->t", first_edge, second_edge)
    determinant = first_dot_first * second_dot_second - first_dot_second ** 2
    safe_determinant = np.where(np.abs(determinant) < 1e-18, 1.0, determinant)

    right_first = radii[:, 0] - radii[:, 1]
    right_second = radii[:, 0] - radii[:, 2]
    first_weight = (
        second_dot_second * right_first - first_dot_second * right_second
    ) / safe_determinant
    second_weight = (
        first_dot_first * right_second - first_dot_second * right_first
    ) / safe_determinant

    in_plane_normal = (
        first_weight[:, None] * first_edge + second_weight[:, None] * second_edge
    )
    in_plane_squared = np.einsum("tj,tj->t", in_plane_normal, in_plane_normal)

    plane_axis = np.cross(first_edge, second_edge)
    axis_length = np.linalg.norm(plane_axis, axis=1)
    exists = (
        (np.abs(determinant) >= 1e-18)
        & (axis_length > 1e-12)
        & (in_plane_squared < _MAX_TANGENT_IN_PLANE)
    )
    plane_axis = plane_axis / np.maximum(axis_length, 1e-300)[:, None]
    out_of_plane_scale = np.sqrt(np.maximum(1.0 - in_plane_squared, 0.0))
    return in_plane_normal, out_of_plane_scale, plane_axis, exists


def prysmoid_distances(
    points: np.ndarray, centers: np.ndarray, radii: np.ndarray
) -> np.ndarray:
    """(M, T) exact signed distance to T triangular slabs.

    ``centers`` is (T, 3, 3), ``radii`` is (T, 3).

    The minimum of ``|p - c(lambda)| - r(lambda)`` over the triangle of barycentric weights
    is attained either in the interior or on a face. At an interior stationary point the
    direction from the interpolated centre to the point is the common tangent normal, which
    collapses the term to a plain plane distance; the faces are the three edges, whose
    minima are the round cones, and the corners, which the round cones already cover. So the
    exact answer is the smallest of the three edge terms and -- only where the triangle of
    tangency points actually contains the point's projection -- the plane term.
    """
    points = np.ascontiguousarray(points, dtype=np.float64)
    centers = np.ascontiguousarray(centers, dtype=np.float64)
    radii = np.ascontiguousarray(radii, dtype=np.float64)

    best = np.full((points.shape[0], centers.shape[0]), np.inf)
    for first, second in ((0, 1), (1, 2), (2, 0)):
        best = np.minimum(
            best,
            round_cone_distances(
                points,
                centers[:, first], radii[:, first],
                centers[:, second], radii[:, second],
            ),
        )

    in_plane_normal, out_of_plane_scale, plane_axis, exists = tangent_plane(centers, radii)
    if not exists.any():
        return best

    # The stationary normal points from the interpolated centre towards the point, so its
    # out-of-plane sign is simply the side of the centre triangle the point lies on.
    offset_from_first = points[:, None, :] - centers[None, :, 0, :]
    side = np.sign(np.einsum("mtj,tj->mt", offset_from_first, plane_axis))
    side = np.where(side == 0.0, 1.0, side)

    normal = (
        in_plane_normal[None, :, :]
        + (side * out_of_plane_scale[None, :])[..., None] * plane_axis[None, :, :]
    )                                                                    # (M, T, 3)
    plane_offset = np.einsum("mtj,tj->mt", normal, centers[:, 0]) + radii[None, :, 0]
    plane_distance = np.einsum("mtj,mj->mt", normal, points) - plane_offset

    # The tangency points are the corners of the flat face. The point's projection has to
    # land inside their triangle for the interior stationary point to be the real minimum.
    tangency = centers[None, :, :, :] + radii[None, :, :, None] * normal[:, :, None, :]
    projected = points[:, None, :] - plane_distance[..., None] * normal

    usable = _inside_triangle(projected, tangency, normal) & exists[None, :]
    return np.where(usable, np.minimum(best, plane_distance), best)


def _inside_triangle(
    projected: np.ndarray, corners: np.ndarray, normal: np.ndarray
) -> np.ndarray:
    """(M, T) test that each projected point lies inside its triangle of corners.

    ``projected`` is (M, T, 3), ``corners`` is (M, T, 3, 3), ``normal`` is (M, T, 3).

    The test is that the three edge cross products agree in sign, not that they are all
    positive. A triangle of tangency points is wound one way against the normal of the face
    it belongs to and the other way against the opposite face's normal, so demanding a
    particular sign silently rejects every point under one of the two faces.
    """
    turn = np.empty(projected.shape[:2] + (3,))
    for corner in range(3):
        edge = corners[:, :, (corner + 1) % 3, :] - corners[:, :, corner, :]
        to_point = projected - corners[:, :, corner, :]
        turn[:, :, corner] = np.einsum("mtj,mtj->mt", np.cross(edge, to_point), normal)
    return np.all(turn >= -1e-12, axis=2) | np.all(turn <= 1e-12, axis=2)


# ------------------------------------------------------------------------------- graph


class BumperGraph:
    """The bumper set a connection list generates, and the links the watchdog walks.

    Adjacency mirrors what the solver can traverse in a single step:

    * a sphere is adjacent to every cone incident to it;
    * a cone is adjacent to both its spheres, and to every prysmoid or quad carrying it as
      a rim edge;
    * a prysmoid or quad is adjacent to its rim cones, and to any other slab sharing a rim
      edge with it.

    Two bumpers that merely overlap in space are *not* adjacent, which is exactly the
    failure mode the watchdog suffers from and the reason this class is kept separate from
    every geometric query.
    """

    def __init__(self, num_spheres: int, connections: Iterable[Sequence[int]]):
        self.num_spheres = int(num_spheres)
        self.connections = [
            tuple(int(index) for index in connection) for connection in connections
        ]

        self.bumpers: list[Bumper] = [
            Bumper(SPHERE, (index,)) for index in range(self.num_spheres)
        ]
        self._index_of: dict[tuple[str, tuple[int, ...]], int] = {
            (SPHERE, (index,)): index for index in range(self.num_spheres)
        }

        slab_kind_by_size = {3: PRYSMOID, 4: QUAD}
        cone_edges: set[tuple[int, int]] = set()
        slab_specs: list[tuple[str, tuple[int, ...]]] = []
        for connection in self.connections:
            if len(set(connection)) != len(connection):
                raise ValueError(f"connection {connection} repeats a sphere")
            if len(connection) == 2:
                cone_edges.add(_ordered(*connection))
                continue
            if len(connection) not in slab_kind_by_size:
                raise ValueError(
                    f"connection {connection} spans {len(connection)} spheres; only 2, 3 "
                    "and 4 are collision primitives"
                )
            kind = slab_kind_by_size[len(connection)]
            slab_specs.append((kind, connection))
            cone_edges.update(Bumper(kind, connection).edges())

        for edge in sorted(cone_edges):
            self._append(Bumper(CONE, edge))
        for kind, spheres in slab_specs:
            self._append(Bumper(kind, spheres))

        self.adjacency: list[set[int]] = [set() for _ in self.bumpers]
        slabs_by_edge: dict[tuple[int, int], list[int]] = {}
        for bumper_index, bumper in enumerate(self.bumpers):
            if bumper.kind == CONE:
                first, second = bumper.spheres
                self._link(bumper_index, self._index_of[(SPHERE, (first,))])
                self._link(bumper_index, self._index_of[(SPHERE, (second,))])
            elif bumper.kind in (PRYSMOID, QUAD):
                for edge in bumper.edges():
                    self._link(bumper_index, self._index_of[(CONE, edge)])
                    slabs_by_edge.setdefault(edge, []).append(bumper_index)
        for sharing in slabs_by_edge.values():
            for position, first in enumerate(sharing):
                for second in sharing[position + 1:]:
                    self._link(first, second)

    def _append(self, bumper: Bumper) -> int:
        key = (bumper.kind, bumper.spheres)
        if key in self._index_of:
            return self._index_of[key]
        self._index_of[key] = len(self.bumpers)
        self.bumpers.append(bumper)
        return self._index_of[key]

    def _link(self, first: int, second: int) -> None:
        self.adjacency[first].add(second)
        self.adjacency[second].add(first)

    def index_of(self, kind: str, spheres: Sequence[int]) -> int:
        spheres = tuple(int(index) for index in spheres)
        if kind == CONE:
            spheres = _ordered(*spheres)
        return self._index_of[(kind, spheres)]

    def counts(self) -> dict[str, int]:
        tally = {SPHERE: 0, CONE: 0, PRYSMOID: 0, QUAD: 0}
        for bumper in self.bumpers:
            tally[bumper.kind] += 1
        return tally

    def components(self) -> list[list[int]]:
        """Connected components of the bumper graph, largest first.

        More than one means a cloth node can never walk from one part of the body to
        another, so every crossing costs a brute-force reacquisition.
        """
        return _components(len(self.bumpers), self.adjacency)

    def sphere_graph_components(self) -> list[list[int]]:
        """Connected components of the plain sphere-to-sphere connection graph."""
        neighbours: list[set[int]] = [set() for _ in range(self.num_spheres)]
        for connection in self.connections:
            for position, first in enumerate(connection):
                for second in connection[position + 1:]:
                    neighbours[first].add(second)
                    neighbours[second].add(first)
        return _components(self.num_spheres, neighbours)

    def distances(
        self, points: np.ndarray, centers: np.ndarray, radii: np.ndarray
    ) -> np.ndarray:
        """(M, B) exact signed distance from every point to every bumper."""
        points = np.ascontiguousarray(points, dtype=np.float64)
        centers = np.ascontiguousarray(centers, dtype=np.float64)
        radii = np.ascontiguousarray(radii, dtype=np.float64)
        result = np.empty((points.shape[0], len(self.bumpers)), dtype=np.float64)

        columns_by_kind: dict[str, list[int]] = {SPHERE: [], CONE: [], PRYSMOID: [], QUAD: []}
        for bumper_index, bumper in enumerate(self.bumpers):
            columns_by_kind[bumper.kind].append(bumper_index)

        if columns_by_kind[SPHERE]:
            columns = np.array(columns_by_kind[SPHERE])
            owned = np.array([self.bumpers[index].spheres[0] for index in columns])
            result[:, columns] = sphere_distances(points, centers[owned], radii[owned])
        if columns_by_kind[CONE]:
            columns = np.array(columns_by_kind[CONE])
            pairs = np.array([self.bumpers[index].spheres for index in columns])
            result[:, columns] = round_cone_distances(
                points,
                centers[pairs[:, 0]], radii[pairs[:, 0]],
                centers[pairs[:, 1]], radii[pairs[:, 1]],
            )
        for kind in (PRYSMOID, QUAD):
            if not columns_by_kind[kind]:
                continue
            columns = np.array(columns_by_kind[kind])
            slab = np.full((points.shape[0], len(columns)), np.inf)
            for position, bumper_index in enumerate(columns):
                triangles = np.array(self.bumpers[bumper_index].triangles())
                slab[:, position] = prysmoid_distances(
                    points, centers[triangles], radii[triangles]
                ).min(axis=1)
            result[:, columns] = slab
        return result

    def owners(
        self,
        points: np.ndarray,
        centers: np.ndarray,
        radii: np.ndarray,
        *,
        tie_tolerance: float = 1e-9,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Owning bumper per point, and the signed distance to the sphere-mesh.

        This is the bumper the solver resolves a node against, so it is also the index the
        watchdog caches between substeps -- which makes getting the tie-break right the
        whole point of the function.

        A cone's distance is the minimum over its whole medial segment, endpoints included,
        so it *ties* with an end sphere wherever that sphere's cap is the nearest surface
        and is strictly smaller only on the lateral band between the tangent circles. The
        same holds for a slab against its rim cones. That mirrors the rendered geometry,
        where ``Spheremesh`` clips each end sphere at its base plane and keeps only the band
        -- the cap belongs to the sphere bumper.

        So ownership goes to the bumper of *lowest dimension* among those attaining the
        minimum: sphere before cone before slab. Taking a plain ``argmin`` instead would
        hand every spherical cap to whichever adjacent cone rounded a hair lower, and the
        owner of a region would flip with floating-point noise -- which is exactly the kind
        of instability the watchdog cannot absorb.
        """
        distance = self.distances(points, centers, radii)
        nearest = distance.min(axis=1)
        dimension = np.array(
            [0 if bumper.kind == SPHERE else 1 if bumper.kind == CONE else 2
             for bumper in self.bumpers]
        )
        attains = distance <= nearest[:, None] + float(tie_tolerance)
        rank = np.where(attains, dimension[None, :], dimension.max() + 1)
        return np.argmin(rank, axis=1), nearest

    def adjacency_matrix(self) -> np.ndarray:
        """(B, B) boolean, True on the diagonal too: a step that stays put is legal."""
        size = len(self.bumpers)
        matrix = np.eye(size, dtype=bool)
        for first, neighbours in enumerate(self.adjacency):
            for second in neighbours:
                matrix[first, second] = True
        return matrix

    def reachable_within(self, steps: int) -> np.ndarray:
        """(B, B) boolean: can the walk get between two bumpers in ``steps`` or fewer."""
        return self.hop_distances() <= int(steps)

    def hop_distances(self) -> np.ndarray:
        """(B, B) number of adjacency steps between every pair of bumpers.

        Unreachable pairs are ``-1``. This, not a yes/no adjacency test, is the quantity
        that describes what the watchdog actually costs: the solver walks until it lands on
        the right bumper, so a node crossing from one bumper to another costs roughly the
        hop distance between them, and only an unreachable pair forces the brute-force
        rescan outright.

        Note that consecutive cones along a chain are *two* hops apart, not one, because the
        walk passes through the sphere they share. Treating that as a break would condemn
        every well-formed limb.
        """
        cached = getattr(self, "_hop_distances", None)
        if cached is not None:
            return cached
        size = len(self.bumpers)
        distance = np.full((size, size), -1, dtype=np.int32)
        for start in range(size):
            distance[start, start] = 0
            frontier = [start]
            step = 0
            while frontier:
                step += 1
                nxt = []
                for current in frontier:
                    for neighbour in self.adjacency[current]:
                        if distance[start, neighbour] < 0:
                            distance[start, neighbour] = step
                            nxt.append(neighbour)
                frontier = nxt
        self._hop_distances = distance
        return distance


def _components(size: int, neighbours: Sequence[set[int]]) -> list[list[int]]:
    seen = [False] * size
    found: list[list[int]] = []
    for start in range(size):
        if seen[start]:
            continue
        stack = [start]
        seen[start] = True
        component: list[int] = []
        while stack:
            current = stack.pop()
            component.append(current)
            for neighbour in neighbours[current]:
                if not seen[neighbour]:
                    seen[neighbour] = True
                    stack.append(neighbour)
        found.append(sorted(component))
    found.sort(key=len, reverse=True)
    return found
